<section class="rv-home" aria-labelledby="rv-title"><div class="rv-page-heading"><div><p class="rv-eyebrow">REVISIÓN DE TIEMPO</p><h1 id="rv-title">Del registro a la aprobación.</h1><p>Trabajado, facturable y aprobado son conceptos distintos. El estado aprobado no representa una factura.</p></div></div>
<?php if ($error): ?><p class="alert alert-error" role="alert"><?= $this->text->e($error) ?></p><?php endif ?>
<?php if (! $rows): ?><article class="rv-panel"><p>No hay sesiones visibles para tu usuario.</p></article><?php endif ?>
<?php foreach ($rows as $row): ?><article class="rv-panel"><h2><?= $this->text->e($row['task_title'].' / '.$row['subtask_title']) ?></h2><p>Usuario #<?= (int) $row['user_id'] ?> · <?= (int) $row['duration_seconds'] ?> s · <?= $row['status'] === 'approved' ? 'Aprobado' : 'Pendiente' ?> · <?= $row['billable'] === null ? 'Sin clasificar' : ((int) $row['billable'] === 1 ? 'Facturable' : 'No facturable') ?></p><p><?= $this->text->e($row['note']) ?></p>
<?php if ($row['can_review'] && (int) $row['end'] > 0): ?><details class="rv-advanced"><summary><?= $row['status'] === 'pending' ? 'Clasificar y aprobar' : 'Rectificar con auditoría' ?></summary>
<form class="rv-entry-form" method="post" action="<?= $this->url->href('RvReviewController', 'save', array('plugin' => 'RvSoftware')) ?>"><?= $this->form->csrf() ?><input type="hidden" name="session_id" value="<?= (int) $row['id'] ?>"><input type="hidden" name="operation_key" value="<?= bin2hex(random_bytes(16)) ?>">
<label>Clasificación<select name="billable" required><option value="">Selecciona</option><option value="0" <?= $row['billable'] !== null && (int) $row['billable'] === 0 ? 'selected' : '' ?>>No facturable</option><option value="1" <?= (int) $row['billable'] === 1 ? 'selected' : '' ?>>Facturable</option></select></label>
<?php if ($row['status'] === 'approved'): ?><label>Fin de sesión<input type="datetime-local" name="end_at" step="1" value="<?= $this->text->e((new DateTimeImmutable('@'.$row['end']))->setTimezone(new DateTimeZone('America/Bogota'))->format('Y-m-d\TH:i:s')) ?>" required></label><label>Duración en segundos<input name="duration_seconds" type="number" min="0" step="1" value="<?= (int) $row['duration_seconds'] ?>" required></label><label>Nota<textarea name="note"><?= $this->text->e($row['note']) ?></textarea></label><?php endif ?>
<label>Bolsa para trabajo facturable<select name="bag_id"><option value="0">Selecciona una bolsa</option><?php foreach ($row['bags'] as $bag): ?><?php if (! $bag['archived'] || (int)$row['bag_id'] === (int)$bag['id']): ?><option value="<?= (int)$bag['id'] ?>" <?= (int)$row['bag_id'] === (int)$bag['id'] ? 'selected' : '' ?>><?= $this->text->e($bag['name']) ?> · saldo <?= (int)$bag['balance_seconds'] ?> s<?= (int)$row['duration_seconds'] > (int)$bag['balance_seconds'] ? ' · puede exceder el saldo' : '' ?></option><?php endif ?><?php endforeach ?></select></label><p>Al aprobar trabajo facturable se consume la bolsa. Se permite excedente; el saldo puede ser negativo. La vigencia corresponde a la fecha trabajada.</p><label>Motivo<input name="reason" <?= $row['status'] === 'approved' ? 'required' : '' ?>></label>
<?php if ($row['status'] === 'pending'): ?><button class="btn" name="operation" value="classify">Guardar clasificación</button> <button class="btn btn-blue" name="operation" value="approve">Aprobar trabajo</button><?php else: ?><button class="btn btn-blue" name="operation" value="rectify">Guardar rectificación</button><?php endif ?></form></details><?php endif ?></article><?php endforeach ?></section>
